        m = len(s)
        if m <= 1:
            return True

        # All zeros case is a valid GP
        if all(x == 0 for x in s):
            return True

        # If first element is 0 but not all are, cannot be GP
        if s[0] == 0:
            return False

        # Calculate common ratio from first two elements
        ratio = float(s[1]) / float(s[0])

        # Verify each subsequent element
        for i in range(2, m):
            if abs(s[i] - ratio * s[i-1]) > 1e-9:
                return False

        return True

    # Check if sequence is already a GP
    if is_gp(seq):
        return '0\n'

    # Try removing each element and check
    for i in range(len(seq)):
        new_seq = seq[:i] + seq[i+1:]
        if is_gp(new_seq):
            return '1\n'

    return '2\n'
