            if p1 >= len(word) or p2 >= len(word):
                return False
            actual_t1 = get_type(word[p1])
            actual_t2 = get_type(word[p2])
            if actual_t1 == t1 and actual_t2 != t2:
                return False
        return True

    def solve():
        # Find lexicographically smallest word >= s that satisfies rules
        word = list(s)

        # First try the original string s
        if satisfies(word):
            return ''.join(word)

        # Try to increment word lexicographically and check
        def backtrack(start_idx):
            """Backtrack to find smallest valid word > s"""
            for pos in range(start_idx, n):
                # Try changing character at pos to next lexicographic option
                curr_char = word[pos]
                if curr_char not in all_chars:
                    continue
                curr_idx = all_chars.index(curr_char)

                if curr_idx + 1 >= len(all_chars):
                    continue

                # Try each larger character
                for next_idx in range(curr_idx + 1, len(all_chars)):
                    word[pos] = all_chars[next_idx]

                    # Try to fill remaining positions with smallest possible characters
                    for i in range(pos + 1, n):
                        word[i] = all_chars[0]  # Smallest character

                    # Verify the complete word
                    final_word = ''.join(word)
                    if satisfies(word):
                        return final_word

                    # Backtrack: reset this position to next possible char
                    word[pos] = all_chars[next_idx + 1] if next_idx + 1 < len(all_chars) else word[pos]

                # Continue search from next position
                result = backtrack(start_idx + 1)
                if result is not None:
                    return result

            return None

        result = backtrack(0)
        return result if result else "-1"

    return solve()
