        for node in component_nodes:
            for neighbor, edge_id in adj[node]:
                if neighbor not in visited:
                    # Check if we can still add more nodes
                    # We need to ensure connectivity, so add neighbor

                    new_visited = visited | {neighbor}
                    new_comp = component_nodes + [neighbor]

                    dfs(new_comp, new_visited, k_remaining - 1, depth + 1)

