class KMP:
    @staticmethod
    def prefix_function(pattern):
        m = len(pattern)
        pi = [0] * m
        for i in range(1, m):
            j = pi[i-1]
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j-1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j
        return pi

    @staticmethod
    def transition(state, char, failure, pattern):
        j = state
        m = len(pattern)
        while j > 0 and pattern[j] != char:
            j = failure[j-1]
        if j < m and pattern[j] == char:
            j += 1
        return j

