from collections import deque
from math import gcd
from collections import Counter

def solution(input_str):
    lines = input_str.strip().split('\n')
    a = list(map(int, lines[0].split()))
    b = list(map(int, lines[1].split()))

    n = 4

    # Check if multisets match (sorted)
    sorted_a = sorted(a)
    sorted_b = sorted(b)
    if sorted_a != sorted_b:
        return "-1"

    # Check GCD of pairwise differences
    def gcd_diff(arr):
        g = 0
        for i in range(n):
            for j in range(i + 1, n):
                g = gcd(g, abs(arr[i] - arr[j]))
        return g

    if gcd_diff(sorted_a) != gcd_diff(sorted_b):
        return "-1"

    # Check for trivial impossible cases
    if len(set(sorted_a)) == 1 and len(set(sorted_b)) > 1:
        return "-1"
    if len(set(sorted_b)) == 1 and len(set(sorted_a)) > 1:
        return "-1"

    # BFS to find operation sequence
    target = tuple(sorted_b)
    start = tuple(sorted_a)

    if start == target:
        return "0\n"

    # BFS state: tuple of sorted positions
    visited = {start: None}  # state -> (prev_state, operation_x_y)
    queue = deque([start])

    while queue:
        if len(visited) > 20000:  # Limit search space
            return "-1"

        positions = queue.popleft()

        # Generate all possible moves
        for move_idx in range(n):
            for center_idx in range(n):
                if move_idx == center_idx:
                    continue

                # Apply reflection: new_position = 2 * center - current_position
                new_pos_list = list(positions)
                new_pos_list[move_idx] = 2 * positions[center_idx] - positions[move_idx]
                new_state = tuple(sorted(new_pos_list))

