        comp_a = {}  # For set A complement relations
        comp_b = {}  # For set B complement relations

        for i, val in enumerate(p):
            # For set A: if val is in A, then a-val must also be in A
            comp_a_val = a - val
            if comp_a_val in val_to_idx:
                other_idx = val_to_idx[comp_a_val]
                if i not in comp_a:
