    return "-1"

def is_valid(n, food):
    if food[0] == 0:
        return False

    # Check circular constraint
    for i in range(2 * n):
        # Check for 3 consecutive same foods
        f1 = food[i]
        f2 = food[(i + 1) % (2 * n)]
        f3 = food[(i + 2) % (2 * n)]
        if f1 == f2 == f3:
            return False

    return True

def format_output(pairs, food, n):
    result = []
    for a, b in pairs:
        result.append(f"{food[a]} {food[b]}")
    return '\n'.join(result)
