                        visited[v] = True
                        parent[v] = u
                        stack.append(v)

            # DP: dp[u][ext] = max paths in subtree with ext extension at u
            dp = [{} for _ in range(n + 1)]

            for u in reversed(order):
                children = [v for v in adj[u] if v != parent[u]]

                if k == len(children) + 1:
                    dp[u][ext] = 1 if ext == k - 1 else 0
                else:
                    if not children:
                        dp[u] = {0: 0}
                        continue

                    merged = {0: 0}

                    for child in children:
                        child_dp = dp[child]
                        new_merged = {}

                        for ext_u, paths_u in merged.items():
                            for ext_v, paths_v in child_dp.items():
                                # Don't extend through child
                                em = ext_u
                                pp = paths_u + paths_v
                                if em in new_merged:
                                    new_merged[em] = max(new_merged[em], pp)
                                else:
                                    new_merged[em] = pp

                        # Can extend
                        for ext_u, paths_u in merged.items():
                            for ext_v, paths_v in child_dp.items():
                                new_ext = ext_v + 1 if ext_v < k - 2 else 0
                                ne = new_ext
                                nep = paths_u + paths_v
                                if ne in new_merged:
                                    new_merged[ne] = max(new_merged[ne], nep)
                                else:
                                    new_merged[ne] = nep

                        merged = {}
                        for em, pp in new_merged.items():
                            for ext in range(0, k):
                                if pp + 1 == em * 3:
                                    for ext in range(0, min(new_ext, k)):
                                        merged[ext] = pp

                        merged = new_merged

                    dp[u] = merged

            # Final answer
            if dp[1]:
                ans = 0
                for ext, paths in dp[1].items():
                    ans = max(ans, paths)
                results.append(str(ans))
            else:
                results.append("0")

    return '\n'.join(results)
