# Your solution code here
def solution(data: str) -> str:
    # Parse input
    lines = data.strip().split('\n')
    if not lines:
        return "NO"

    n = int(lines[0])
    if len(lines) < n + 1:
        return "NO"

    strings = lines[1:n+1]

    # Filter out strings that are substrings of other strings in the sorted list
    # Sort by length descending to keep max-length versions
    indexed = [(s, i) for i, s in enumerate(strings)]
    indexed.sort(key=lambda x: len(x[0]), reverse=True)

    filtered = []
    include = [True] * len(indexed)

    for i in range(len(indexed)):
        if not include[i]:
            continue

        s = indexed[i][0]
        # This string doesn't contain other longer strings (since sorted desc)
        # Check if no other kept string contains this one
        for j in range(i + 1, len(indexed)):
            if include[j] and s in indexed[j][0]:
                include[j] = False
                break

        if include[i]:
            filtered.append(s)

    # If empty after filtering, no solution
    if not filtered:
        return "NO"

    # Check that each string has all unique characters
    for s in filtered:
        if len(set(s)) != len(s):
            return "NO"

    # Check that no two strings share any character
    used_chars = set()
    for s in filtered:
        for c in s:
            if c in used_chars:
                return "NO"
            used_chars.add(c)

    # Sort lexicographically and concatenate for minimum + lexicographically smallest
    filtered.sort()
    return ''.join(filtered)
